 * `colors.ts` remains the typed JS mirror for inline `style={{…}}` callers
 * and must stay in sync with this file.
 */

:root {
  /* Tells the UA which palette native controls (scrollbars, form widgets,
   * the overscroll gutter) should use. Without this a dark-mode page still
   * gets light scrollbars and a white rubber-band background on macOS/iOS. */
  color-scheme: light;

  /* bg */
  --om-bg-app: #faf9f5;
  --om-bg-panel: #f8f7f3;
  --om-bg-surface: #ffffff;
  --om-bg-elevated: #ffffff;
  --om-bg-hover: rgba(15, 12, 8, 0.04);
  /* --om-bg-hover flattened over surface, for elements floating over
   * arbitrary content. Keep ink/alpha in sync with --om-bg-hover. */
  --om-bg-hover-opaque: color-mix(
    in srgb,
    rgb(15, 12, 8) 4%,
    var(--om-bg-surface)
  );
  --om-bg-active: #e8e6dc;
  --om-bg-selected: #e3dacc;
  --om-bg-muted: #f0eee6;
  --om-bg-stripe: rgba(15, 12, 8, 0.02);
  --om-bg-tint-design-system: #f6e3e3;
  --om-bg-tint-template: #e4e2f1;
  --om-bg-primary-tab-bar: #e8e6dc;
  --om-bg-secondary-tab-bar: #f6f5f0af;
  --om-bg-error-tint: rgba(166, 50, 68, 0.05);
  --om-bg-intro-splash: #e1dacd;
  /* Sliding-thumb fill for segmented controls (DcPropsPanel). White in
   * light — bg-selected there reads as a second tint, not a thumb — and
   * the selected tone in dark, where white would glare. */
  --om-bg-thumb: #ffffff;
  /* Modal/popover backdrop. Darker in dark mode so the panel still
   * separates from the page; a fixed dark scrim on a dark page reads
   * as no scrim at all. */
  --om-bg-scrim: rgba(15, 12, 8, 0.4);

  /* border */
  --om-border-subtle: rgba(15, 12, 8, 0.08);
  --om-border-card: rgba(15, 12, 8, 0.12);
  --om-border-default: rgba(15, 12, 8, 0.1);
  --om-border-strong: rgba(15, 12, 8, 0.22);
  --om-border-focus: rgba(15, 12, 8, 0.36);
  --om-border-modal: rgba(0, 0, 0, 0.1);

