:root[data-theme='dark'] {
  color-scheme: dark;

  /* bg */
  --om-bg-app: #1c1b19;
  --om-bg-panel: #222220;
  --om-bg-surface: #2a2927;
  --om-bg-elevated: #2a2927;
  --om-bg-hover: rgba(250, 249, 245, 0.13);
  /* See the light-theme note: hover wash flattened over surface. */
  --om-bg-hover-opaque: color-mix(
    in srgb,
    rgb(250, 249, 245) 13%,
    var(--om-bg-surface)
  );
  --om-bg-active: #35332c;
  --om-bg-selected: #3c392f;
  --om-bg-muted: #2e2c26;
  --om-bg-stripe: rgba(250, 249, 245, 0.02);
  --om-bg-tint-design-system: #3a2a2a;
  --om-bg-tint-template: #2a2838;
  --om-bg-primary-tab-bar: #35332c;
  --om-bg-secondary-tab-bar: #222220af;
  --om-bg-error-tint: rgba(196, 90, 106, 0.12);
  --om-bg-intro-splash: #2e2a22;
  --om-bg-thumb: #3c392f;
  --om-bg-scrim: rgba(0, 0, 0, 0.6);

  /* border */
  --om-border-subtle: rgba(250, 249, 245, 0.1);
  --om-border-card: rgba(250, 249, 245, 0.14);
  --om-border-default: rgba(250, 249, 245, 0.12);
  --om-border-strong: rgba(250, 249, 245, 0.24);
  --om-border-focus: rgba(250, 249, 245, 0.4);
  --om-border-modal: rgba(250, 249, 245, 0.12);

  /* text */
  --om-text-primary: rgba(250, 249, 245, 0.92);
  --om-text-prose: rgba(250, 249, 245, 0.8);
  --om-text-secondary: rgba(250, 249, 245, 0.64);
  --om-text-tertiary: rgba(250, 249, 245, 0.6);
  --om-text-disabled: rgba(250, 249, 245, 0.32);
  --om-text-design-system-badge: #d89a9a;
  --om-text-inverse: #1c1b19;
  --om-text-link: #7eaeda;

  /* accent */
  --om-accent-primary: #e08968;
  --om-accent-primary-bg: rgba(224, 137, 104, 0.16);
  --om-accent-primary-tint: rgba(224, 137, 104, 0.06);
  --om-accent-primary-hover: #e89b7e;
  --om-accent-primary-active: #efad94;
  --om-accent-secondary: #7eaeda;
  --om-accent-secondary-hover: #91bce2;
  --om-accent-secondary-active: #a4c9e9;
  --om-accent-success: #6fa859;
  --om-accent-sage: #8fae6a;
  --om-accent-warning: #dabe4a;
  /* ≥4.5:1 on bg.surface (#2a2927) and on the error-tint composite
