/* Point the kit's property-panel grammar (the pp- tokens, kit
 * tokens.css) at the om- palette, so the shared row-wells
 * (kit/panel.tsx, kit/prop-rows.tsx) read as this editor's own surface.
 * :root:root out-ranks the kit's :root defaults, which ship later in
 * the compiled stylesheet than this file. */
:root:root {
  --pp-row-bg: var(--om-bg-elevated);
  --pp-line: var(--om-border-default);
  --pp-label: var(--om-text-tertiary);
  --pp-value: var(--om-text-primary);
  --pp-seg: var(--om-bg-selected);
  --pp-hover: var(--om-bg-hover);
  --pp-check: var(--om-accent-blue);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  /* Tailwind's border-width utilities only set the width — the UA default
     is `border-style: none`, so a bare `border` class would paint nothing.
     Tailwind preflight normally supplies this reset, but preflight is off
     here (this file owns the reset). Every component sets its own border
     colour via `border-om-*`, so no default colour is needed. */
  border-width: 0;
  border-style: solid;
}

/* The UA stylesheet sets Arial on form controls. Components used to
   override this per-element with `font-family: inherit`; apply it once
   here instead. */
button,
input,
select,
textarea {
  font-family: inherit;
}

/* The UA paints <button> with a gray face (Chromium: rgb(239,239,239)).
   Tailwind preflight — which normally zeroes it — is off here, and this
   reset never covered it, so the UA fill leaked through every button
   that doesn't set its own background: the shared-kit toolbar's ghost
   buttons rendered as gray pills instead of the transparent treatment
   every other appifact family shows. Every component in this editor
   sets its background explicitly, so transparent is the only correct
   default. */
button {
  background-color: transparent;
}

/* Chrome/WebKit paint autofilled inputs with a UA-fixed pale-yellow/blue
   fill and near-black text that ignores the theme — unreadable on dark
   surfaces. The inset-shadow trick is the only way to repaint the UA
   layer; the text and caret follow the theme ink. */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus {
  -webkit-box-shadow: 0 0 0 1000px var(--om-bg-surface) inset;
  -webkit-text-fill-color: var(--om-text-primary);
  caret-color: var(--om-text-primary);
}

/* Native checkbox/radio glyphs default to the UA accent (Chrome blue),
   which clashes with both palettes. Host-side only — preview iframes have
   their own documents and never see this sheet. */
input[type='checkbox'],
input[type='radio'] {
  accent-color: var(--om-accent-primary);
}

/* CDS components (CoachMark, Dialog, LimitUpsellOptionCard) render titles
   as <h2>/<h3> and rely on the host app's preflight-style heading reset for
   the type-scale tokens to take effect. Preflight is off here, so without
   this the UA defaults (h2=1.5em bold, h3=1.17em) leak through every CDS
   island. Scoped to .cds-root so omelette's own non-CDS headings (which set
   explicit sizes) aren't affected. */
.cds-root :where(h1, h2, h3, h4, h5, h6) {
  font-size: inherit;
  font-weight: inherit;
  margin: 0;
}
.cds-root :where(p) {
  margin: 0;
}

html {
  /* No boundary action on either axis at the root. X: a two-finger
     trackpad pan inside canvas-style artifacts (served in a
     cross-origin iframe) overscrolls to the viewport and triggers the
     browser's swipe-to-go-back gesture, navigating away mid-edit. Y:
     an unconsumed downward overscroll at a scrolled-to-top root is
     exactly the gesture an iOS app hosting the artifact in a sheet
     reads as drag-to-dismiss — and a pull-to-refresh mid-edit reloads
     the editor out from under the session (the restore banner is
     recovery, not prevention). The editor is an app shell (fixed
     h-screen layout, inner scrollers own their own overscroll), so
     neither axis has a legitimate root boundary action. */
  overscroll-behavior: none;
}

iframe {
  /* The host page (claude.ai's artifact wrapper) ships a CSS reset that can
     hide src-less iframes; the canvas preview is srcDoc-only, so it
     disappeared. Keep every iframe explicitly block so preview frames
     always paint regardless of the embedding page's resets. */
  display: block;
  /* :root sets `color-scheme` so native UI tracks the app theme, but it's
     an inherited property: a transparent preview iframe whose embedded
     document is light would inherit `dark` here, and Chromium paints an
     opaque backdrop when the embedder's color-scheme disagrees with the
     document's — the iframe stops being transparent. Resetting at the
     element means every preview frame stays see-through regardless of
     app theme; an iframe that *wants* a themed backdrop can opt back in. */
  color-scheme: normal;
}

html,
body {
  margin: 0;
  padding: 0;
  font-family:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: var(--om-bg-app);
  color: var(--om-text-primary);
}

a {
  color: inherit;
  text-decoration: none;
}

/* Thin overlay scrollbar — used by the chat view, DC editor panel, and
   picker popups. Elements opt in via `className="om-scrollbar"` instead of
   restyling the pseudo-elements locally. */
.om-scrollbar {
  scrollbar-width: thin;
  scrollbar-color: var(--om-scrollbar-thumb) transparent;
}
.om-scrollbar::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.om-scrollbar::-webkit-scrollbar-track {
  background: transparent;
}
.om-scrollbar::-webkit-scrollbar-thumb {
  background: var(--om-scrollbar-thumb);
  border-radius: 3px;
}
.om-scrollbar::-webkit-scrollbar-thumb:hover {
  background: var(--om-scrollbar-thumb-hover);
}

/* Theme-switch transition mute. useTheme sets data-theme-switching on
   <html> for the frames around a data-theme write so components with
   `transition: background/color …` snap to the new palette together
   instead of shimmering at their individual durations. */
html[data-theme-switching] *,
html[data-theme-switching] *::before,
html[data-theme-switching] *::after {
  transition: none !important;
}

